/**
 * Tailwind's file scanner relies on the native `@tailwindcss/oxide` binding.
 * Some Windows machines (including the one this concept was built on) block
 * unsigned native modules through Application Control, so the scanner silently
 * falls back to a WASI build that cannot walk the filesystem.
 *
 * This script extracts class-like tokens from the source and writes them into
 * `src/app/safelist.css` using Tailwind's `@source inline(...)` directive.
 * The generated file is imported by `globals.css`, so utilities are still
 * produced on machines where filesystem scanning is unavailable.
 *
 * Run automatically through `predev` and `prebuild`.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, extname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourceRoot = join(root, "src");
const output = join(sourceRoot, "app", "safelist.css");
const extensions = new Set([".ts", ".tsx", ".js", ".jsx", ".mdx"]);

function walk(directory) {
  const entries = readdirSync(directory, { withFileTypes: true });
  return entries.flatMap((entry) => {
    const full = join(directory, entry.name);
    if (entry.isDirectory()) return walk(full);
    return extensions.has(extname(entry.name)) ? [full] : [];
  });
}

/**
 * Keep only tokens that can plausibly be a Tailwind candidate. Prose and
 * source fragments with unbalanced brackets must be removed: an invalid token
 * inside `@source inline(...)` causes the rest of that directive to be dropped.
 */
function isCandidate(token) {
  if (token.length < 2 || token.length > 140) return false;
  if (!/[a-zA-Z]/.test(token)) return false;
  if (/["'`\\{}]/.test(token)) return false;
  if (/^[.#/,;(]/.test(token)) return false;
  if (/[.,;:!?]$/.test(token)) return false;

  let square = 0;
  let round = 0;

  for (const character of token) {
    if (character === "[") square += 1;
    else if (character === "]") square -= 1;
    else if (character === "(") round += 1;
    else if (character === ")") round -= 1;

    if (square < 0 || round < 0) return false;

    const insideBrackets = square > 0 || round > 0;
    if (!insideBrackets && "()<>=&*+~|^$?;#,".includes(character)) return false;
    if (!insideBrackets && character === "." && token.indexOf(".") === 0) return false;
  }

  return square === 0 && round === 0;
}

const tokens = new Set();
const stringLiteral = /(["'`])((?:\\.|(?!\1)[\s\S])*?)\1/g;

for (const file of walk(sourceRoot)) {
  if (file === output) continue;
  const source = readFileSync(file, "utf8");
  for (const match of source.matchAll(stringLiteral)) {
    const value = match[2];
    if (value.includes("${")) continue;
    for (const token of value.split(/\s+/)) {
      if (isCandidate(token)) tokens.add(token);
    }
  }
}

const sorted = [...tokens].sort();
const chunks = [];
let current = [];

for (const token of sorted) {
  const candidate = [...current, token].join(" ");
  if (candidate.length > 900 && current.length > 0) {
    chunks.push(current.join(" "));
    current = [token];
  } else {
    current.push(token);
  }
}
if (current.length > 0) chunks.push(current.join(" "));

const css = [
  "/* Generated by scripts/generate-safelist.mjs. Do not edit by hand. */",
  ...chunks.map((chunk) => `@source inline("${chunk}");`),
  "",
].join("\n");

writeFileSync(output, css, "utf8");
console.log(`[safelist] ${sorted.length} candidates across ${chunks.length} directives`);
